271|        sessionId,
272|        {
273|          question: text,
274|          filePath: null,
275|          symbols: [],
276|          cardId: null,
277|          ...(changeId !== null ? { changeId } : {}),
278|        } as AskRequest,
279|        { signal: controller.signal },
